def solve(inputs: dict) -> float:
    M = inputs.get('M') or [[9, 26], [13, 16]]
    exp = int(inputs.get('exp', 37))
    mod = int(inputs.get('mod', 370583))
    A = [row[:] for row in M]
    # identity
    R = [[1, 0], [0, 1]]
    def mul(X, Y):
        return [[(X[0][0]*Y[0][0] + X[0][1]*Y[1][0]) % mod,
                 (X[0][0]*Y[0][1] + X[0][1]*Y[1][1]) % mod],
                [(X[1][0]*Y[0][0] + X[1][1]*Y[1][0]) % mod,
                 (X[1][0]*Y[0][1] + X[1][1]*Y[1][1]) % mod]]
    while exp > 0:
        if exp & 1:
            R = mul(R, A)
        A = mul(A, A)
        exp >>= 1
    return float((R[0][0] + R[0][1] + R[1][0] + R[1][1]) % mod)

